WITH prev_events AS (SELECT *, LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) AS prev_txn_time FROM transactions), flagged AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_burst FROM prev_events), sessions_transactions AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT id, txn_type, amount, is_flagged, is_new_burst, burst_id, CASE WHEN txn_type RLIKE '^(CREDIT|DEBIT)$' THEN 'EXTENDED' WHEN txn_type RLIKE '^(REFUND|FEE)$' THEN 'PRIORITY' ELSE 'OTHER_ZONE' END AS txn_type_zone FROM sessions_transactions ORDER BY burst_id NULLS LAST
